import React, { useState, useEffect } from 'react';
import { getSensorReadings, getAllTopics } from '../api/api';

function RawDataPage() {
  // State for the data
  const [dataList, setDataList] = useState([]);
  const [topics, setTopics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // State for filters
  const [topicInput, setTopicInput] = useState("");
  const [startInput, setStartInput] = useState("");
  const [endInput, setEndInput] = useState("");

  // State for paging
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalRecords, setTotalRecords] = useState(0);

  // This function gets the data
  const fetchMyData = async () => {
    setLoading(true);
    setError("");
    try {
      // Beginners usually call APIs one by one
      const response = await getSensorReadings({
        page: page,
        pageSize: 20,
        topic: topicInput !== "" ? topicInput : null,
        startTime: startInput !== "" ? startInput : null,
        endTime: endInput !== "" ? endInput : null
      });

      setDataList(response.data);
      setTotalPages(response.pagination.total_pages);
      setTotalRecords(response.pagination.total_count);

      const topicResponse = await getAllTopics();
      setTopics(topicResponse.topics);

      setLoading(false);
    } catch (err) {
      setError("Failed to load the table data");
      setLoading(false);
    }
  };

  // Run when page number changes
  useEffect(() => {
    fetchMyData();
  }, [page]);

  // Function for the search button
  const handleSearch = () => {
    setPage(1); // reset to first page
    fetchMyData();
  };

  // Function to clear everything
  const handleClear = () => {
    setTopicInput("");
    setStartInput("");
    setEndInput("");
    setPage(1);
    // The useEffect will trigger fetch because of the page change
  };

  return (
    <div style={{ padding: '20px' }}>
      <h2>Raw Sensor Data</h2>
      <p>Total Records found: {totalRecords}</p>

      {/* Filter Box */}
      <div style={{ border: '1px solid #ccc', padding: '15px', marginBottom: '20px' }}>
        <h4 style={{ marginTop: '0' }}>Filter Options</h4>
        <div style={{ display: 'flex', gap: '15px', flexWrap: 'wrap' }}>
          <div>
            <label>Device:</label><br/>
            <select value={topicInput} onChange={(e) => setTopicInput(e.target.value)}>
              <option value="">All Devices</option>
              {topics.map(t => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>

          <div>
            <label>Start Time:</label><br/>
            <input type="datetime-local" value={startInput} onChange={(e) => setStartInput(e.target.value)} />
          </div>

          <div>
            <label>End Time:</label><br/>
            <input type="datetime-local" value={endInput} onChange={(e) => setEndInput(e.target.value)} />
          </div>

          <div style={{ display: 'flex', alignItems: 'flex-end', gap: '5px' }}>
            <button onClick={handleSearch}>Search</button>
            <button onClick={handleClear}>Clear</button>
          </div>
        </div>
      </div>

      {/* The Table */}
      {loading == true ? (
        <p>Loading table data...</p>
      ) : error != "" ? (
        <p style={{ color: 'red' }}>{error}</p>
      ) : (
        <div>
          <table border="1" style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead style={{ background: '#f2f2f2' }}>
              <tr>
                <th>ID</th>
                <th>Device</th>
                <th>Temp</th>
                <th>Humid</th>
                <th>Volt</th>
                <th>Curr</th>
                <th>Time</th>
              </tr>
            </thead>
            <tbody>
              {dataList.map((item) => (
                <tr key={item.id}>
                  <td>{item.id}</td>
                  <td style={{ fontSize: '12px' }}>{item.topic}</td>
                  <td>{item.temperature != null ? item.temperature : "—"}</td>
                  <td>{item.humidity != null ? item.humidity : "—"}</td>
                  <td>{item.voltage != null ? item.voltage : "—"}</td>
                  <td>{item.current != null ? item.current : "—"}</td>
                  <td style={{ fontSize: '12px' }}>{new Date(item.received_at).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Simple Pagination */}
          <div style={{ marginTop: '20px', display: 'flex', gap: '10px', alignItems: 'center' }}>
            <button disabled={page == 1} onClick={() => setPage(1)}>First</button>
            <button disabled={page == 1} onClick={() => setPage(page - 1)}>Prev</button>
            <span>Page {page} of {totalPages}</span>
            <button disabled={page == totalPages} onClick={() => setPage(page + 1)}>Next</button>
            <button disabled={page == totalPages} onClick={() => setPage(totalPages)}>Last</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default RawDataPage;
